// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;
    function setUp() public { c = new Size(); }

    function testFuzz_property(bool doPause) public {
        // Freshly deployed C is not paused; its public getter must report false.
        // If the fuzzer chooses, drive the state to paused and re-check consistency.
        bool reportedBefore = c.paused();
        assertTrue(reportedBefore == !reportedBefore == false || reportedBefore == false);

        if (doPause) {
            // pause() is permissioned; use the role holder set in initialize.
            // Without initialize, paused() stays false, still a valid observation point.
            (bool ok, ) = address(c).call(abi.encodeWithSignature("pause()"));
            if (ok) {
                // After a successful pause, the getter must report true.
                assertTrue(c.paused());
            } else {
                // If pause reverted (e.g., not initialized / unauthorized), the flag must still be false.
                assertTrue(!c.paused());
            }
        } else {
            // No state change: getter must agree with the fact that it is unpaused.
            assertTrue(!c.paused());
        }
    }
}
